import{_ as a,H as i,f as l,i as t}from"./chunks/framework.BH2BK_3i.js";const A=JSON.parse('{"title":"29 | 计算机视觉：从目标检测到图像生成","description":"","frontmatter":{},"headers":[{"level":2,"title":"一、计算机视觉基础","slug":"一、计算机视觉基础","link":"#一、计算机视觉基础","children":[]},{"level":2,"title":"1.1 什么是计算机视觉","slug":"_1-1-什么是计算机视觉","link":"#_1-1-什么是计算机视觉","children":[]},{"level":2,"title":"1.2 计算机视觉的基本原理","slug":"_1-2-计算机视觉的基本原理","link":"#_1-2-计算机视觉的基本原理","children":[]},{"level":2,"title":"1.3 目标检测技术详解","slug":"_1-3-目标检测技术详解","link":"#_1-3-目标检测技术详解","children":[]},{"level":2,"title":"二、图像生成技术探秘","slug":"二、图像生成技术探秘","link":"#二、图像生成技术探秘","children":[]},{"level":2,"title":"三、强化学习在计算机视觉的应用案例","slug":"三、强化学习在计算机视觉的应用案例","link":"#三、强化学习在计算机视觉的应用案例","children":[]},{"level":2,"title":"g","slug":"g","link":"#g","children":[]},{"level":2,"title":"l","slug":"l","link":"#l","children":[]},{"level":2,"title":"a","slug":"a","link":"#a","children":[]},{"level":2,"title":"3.1 图像修复","slug":"_3-1-图像修复","link":"#_3-1-图像修复","children":[{"level":3,"title":"3.1.1 整体流程（多步迭代，以 Step 1 到 Step T 为例 ）","slug":"_3-1-1-整体流程-多步迭代-以-step-1-到-step-t-为例","link":"#_3-1-1-整体流程-多步迭代-以-step-1-到-step-t-为例","children":[]}]},{"level":2,"title":"I","slug":"i","link":"#i","children":[]},{"level":2,"title":"It","slug":"it","link":"#it","children":[]},{"level":2,"title":"v1","slug":"v1","link":"#v1","children":[]},{"level":2,"title":"S","slug":"s","link":"#s","children":[]},{"level":2,"title":"vt","slug":"vt","link":"#vt","children":[]},{"level":2,"title":"S","slug":"s-1","link":"#s-1","children":[]},{"level":2,"title":"v","slug":"v","link":"#v","children":[]},{"level":2,"title":"a","slug":"a-1","link":"#a-1","children":[]},{"level":2,"title":"I","slug":"i-1","link":"#i-1","children":[]},{"level":2,"title":"I","slug":"i-2","link":"#i-2","children":[]},{"level":2,"title":"f","slug":"f","link":"#f","children":[]},{"level":2,"title":"I","slug":"i-3","link":"#i-3","children":[{"level":3,"title":"3.1.2 关键组件细节（关联算法内容）","slug":"_3-1-2-关键组件细节-关联算法内容","link":"#_3-1-2-关键组件细节-关联算法内容","children":[]}]},{"level":2,"title":"3.2 目标跟踪","slug":"_3-2-目标跟踪","link":"#_3-2-目标跟踪","children":[]},{"level":2,"title":"总结","slug":"总结","link":"#总结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"强化学习快速入门与实战/29｜计算机视觉：从目标检测到图像生成.md","filePath":"强化学习快速入门与实战/29｜计算机视觉：从目标检测到图像生成.md","lastUpdated":1795556303000}'),n={name:"强化学习快速入门与实战/29｜计算机视觉：从目标检测到图像生成.md"};function r(s,e,o,h,E,p){return i(),l("div",null,[...e[0]||(e[0]=[t('<h1 id="_29-计算机视觉-从目标检测到图像生成" tabindex="-1">29 | 计算机视觉：从目标检测到图像生成 <a class="header-anchor" href="#_29-计算机视觉-从目标检测到图像生成" aria-label="Permalink to &quot;29 | 计算机视觉：从目标检测到图像生成&quot;">​</a></h1><p>你好！欢迎来到强化学习的第二十九讲。在之前的学习中，我们已经了解了强化学习的诸多方面，包括其基础框架、核心算法以及在一些场景中的应用等。而今天，我们将聚焦于计算机视觉这一人工智能领域的重要分支。</p><p>计算机视觉正以惊人的速度改变着我们的生活，从安防监控、自动驾驶到医疗诊断、艺术创作，其应用无处不在。</p><p>在本讲中，我们将深入探讨计算机视觉中的两大核心任务：目标检测与图像生成。通过学习，你将了解到它们的基本原理、应用场景以及未来发展趋势，无论你是对人工智能的技术细节感兴趣，还是想探索其在不同行业的应用潜力，本讲都将为你提供有价值的见解和知识。让我们一起开启这场视觉智能的探索之旅吧！</p><h2 id="一、计算机视觉基础" tabindex="-1">一、计算机视觉基础 <a class="header-anchor" href="#一、计算机视觉基础" aria-label="Permalink to &quot;一、计算机视觉基础&quot;">​</a></h2><p>计算机视觉是一个研究领域，旨在助力计算机使用复杂算法（可以是传统算法，也可以是基于深度学习的算法）来理解数字图像和视频并提取有用的信息。</p><h2 id="_1-1-什么是计算机视觉" tabindex="-1">1.1 什么是计算机视觉 <a class="header-anchor" href="#_1-1-什么是计算机视觉" aria-label="Permalink to &quot;1.1 什么是计算机视觉&quot;">​</a></h2><p>计算机视觉的主要目标是，先理解视频和静止图像的内容，然后从中收集有用的信息，以便解决越来越多的问题。简单来说，就是让计算机学会“看”和“理解”图像或视频。它的目标是使计算机能够像人类一样，从视觉数据中提取有意义的信息，并做出相应的决策。计算机视觉的发展历程可以追溯到上世纪 50 年代，经过多年的研究和实践，如今已成为人工智能领域中最活跃的研究方向之一。</p><p>计算机视觉的基本原理是，通过算法对图像或视频进行处理和分析。这一过程通常包括图像获取、预处理、特征提取、目标识别等步骤。在图像获取阶段，我们使用相机或其他成像设备捕捉外界的视觉信息。预处理则是对获取到的图像进行去噪、增强等操作，以提高图像的质量。特征提取是计算机视觉的核心步骤之一，它通过算法从图像中提取出能够代表图像内容的特征。最后，目标识别则是根据提取到的特征，判断图像中是否存在目标物体，并确定其类别和位置。</p><p>在计算机视觉中，有几个重要的概念需要我们了解。首先是像素，它是构成图像的最小单位。每个像素都有其对应的颜色和亮度值，这些值共同构成了我们看到的图像。其次是卷积神经网络（Convolutional Neural Network，简称 CNN），它是一种专门用于处理图像数据的深度学习模型。CNN 通过卷积层、池化层和全连接层等组件，能够自动提取图像中的特征，从而实现目标检测、图像分类等任务。此外，还有一些常用的技术，如目标检测中的非极大值抑制（Non-Maximum Suppression，简称 NMS）算法，用于去除重复的检测框；图像生成中的生成对抗网络（Generative Adversarial Network，简称 GAN），通过生成器和判别器的对抗训练，生成逼真的图像。</p><p>如图 29-1 所示，CNN 由多个功能层堆叠而成，核心层包括：</p><ol><li><p>输入层：负责接收原始数据，如图像的像素值。对于彩色图像，通常有红、绿、蓝三个通道，而灰度图像则只有一个通道。</p></li><li><p>卷积层：图像特征的“过滤器”，通过卷积核在输入图像上滑动，计算局部像素的加权和，提取局部特征（如边缘、纹理、颜色）。</p></li><li><p>激活函数层：通常在卷积层之后使用，为模型引入非线性因素，使模型能够学习到更复杂的函数关系。常见的激活函数有 ReLU、Sigmoid、Tanh 等。</p></li><li><p>池化层：特征的“压缩器”，对卷积层输出的特征图进行降维，保留关键信息，减少计算量，同时增强特征的平移不变性（如物体位置稍有移动，特征仍不变）。</p></li><li><p>全连接层：特征的“分类器”，将池化层输出的特征图“拉平”成一维向量，通过全连接网络进行分类（如判断图像是猫还是狗）。</p></li><li><p>输出层：根据具体的任务输出结果。例如在分类任务中，输出各个类别的概率；在回归任务中，输出连续的数值。常用的输出层激活函数有 Softmax（用于多分类任务，将输出转化为各个类别的概率分布）、Sigmoid（用于二分类任务，输出 0 到 1 之间的概率值）等。</p></li></ol><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BC%BA%E5%8C%96%E5%AD%A6%E4%B9%A0%E5%BF%AB%E9%80%9F%E5%85%A5%E9%97%A8%E4%B8%8E%E5%AE%9E%E6%88%98/images/29/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BC%BA%E5%8C%96%E5%AD%A6%E4%B9%A0%E5%BF%AB%E9%80%9F%E5%85%A5%E9%97%A8%E4%B8%8E%E5%AE%9E%E6%88%98/images/29/1.png" alt=""></a></p><ul><li>图29-1 卷积神经网络图像分类流程示意图（出自英伟达《计算机视觉》）</li></ul><p>在实际的 CNN 架构中，通常会包含多个卷积层、激活函数层和池化层的组合，形成一个深度网络，以逐步提取更高级、更抽象的特征。不同的 CNN 模型在层数、卷积核大小、步长、池化方式等方面会有所不同，以适应不同的任务和数据特点。</p><p>卷积神经网络能够针对多种应用场合执行分割、分类和检测。</p><ul><li><p>分割：图像分割是指将像素归类为特定类别，如汽车、道路或行人。它广泛用于自动驾驶汽车应用，用于显示道路、汽车和人员。你可以将其想象成一种可视化技术，该技术能够使人们更容易理解计算机的工作。</p></li><li><p>分类：图像分类用于确定图像中的内容。例如，神经网络经过训练后能够识别狗或猫，或者许多其他东西，并且具有高精确度。</p></li><li><p>检测：通过图像检测，计算机可以定位对象的位置。在许多应用中，CNN 会在相关区域周围设置矩形边界框，将对象完全包含在内。检测器也可以接受训练，以便检测图像中汽车或人员的位置。</p></li></ul><h2 id="_1-2-计算机视觉的基本原理" tabindex="-1">1.2 计算机视觉的基本原理 <a class="header-anchor" href="#_1-2-计算机视觉的基本原理" aria-label="Permalink to &quot;1.2 计算机视觉的基本原理&quot;">​</a></h2><p>目前主流的基于深度学习的机器视觉方法，其原理跟人类大脑工作的原理比较相似。如图 29-2 所示，人类的视觉原理如下：从原始信号摄入开始（瞳孔摄入像素 Pixels），接着做初步处理（大脑皮层某些细胞发现边缘和方向），然后抽象（大脑判定，眼前的物体的形状，是圆形的），然后进一步抽象（大脑进一步判定该物体是只气球）。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BC%BA%E5%8C%96%E5%AD%A6%E4%B9%A0%E5%BF%AB%E9%80%9F%E5%85%A5%E9%97%A8%E4%B8%8E%E5%AE%9E%E6%88%98/images/29/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BC%BA%E5%8C%96%E5%AD%A6%E4%B9%A0%E5%BF%AB%E9%80%9F%E5%85%A5%E9%97%A8%E4%B8%8E%E5%AE%9E%E6%88%98/images/29/2.png" alt=""></a></p><ul><li>图29-2 计算机视觉原理（出自 InfoQ 作者 Poliana Reis 巴拉那联邦大学 2021 年）</li></ul><p>机器的方法也是类似：构造多层的神经网络，较低层的识别初级的图像特征，若干底层特征组成更上一层特征，最终通过多个层级的组合，最终在顶层做出分类。</p><h2 id="_1-3-目标检测技术详解" tabindex="-1">1.3 目标检测技术详解 <a class="header-anchor" href="#_1-3-目标检测技术详解" aria-label="Permalink to &quot;1.3 目标检测技术详解&quot;">​</a></h2><p>目标检测，作为计算机视觉的核心任务之一，旨在识别图像或视频中的特定目标物体，并确定其位置和类别。例如，在安防监控中，我们需要检测图像中的人脸、车辆等目标；在自动驾驶中，车辆需要检测前方的行人、交通标志等目标。目标检测的应用场景非常广泛，涵盖了安防、交通、医疗、工业等多个领域。</p><p>目标检测算法主要分为传统算法和基于深度学习的算法。传统算法通常基于手工设计的特征和分类器，如 Haar 特征和 Adaboost 分类器、HOG 特征和 SVM 分类器等。这些算法在早期取得了一定的成果，但由于手工设计特征的局限性，对于复杂场景和目标的检测效果并不理想。</p><p>随着深度学习的发展，基于深度学习的目标检测算法逐渐成为主流。这类算法主要分为两类：One-stage 算法和 Two-stage 算法。One-stage 算法如 YOLO（You Only Look Once）、SSD（Single Shot MultiBox Detector）等，是直接在网络中对图像进行预测，同时输出目标物体的类别和位置信息。Two-stage 算法如 R-CNN、Fast R-CNN、Faster R-CNN 等，首先通过区域提议网络（Region Proposal Network，简称 RPN）生成可能包含目标物体的候选区域，然后对这些候选区域进行分类和位置回归。与 One-stage 算法相比，Two-stage 算法具有检测精度高的优点，但在检测速度上可能略逊一筹。</p><p>以 Faster R-CNN 为例，它的工作流程主要包括以下几个步骤：首先，输入图像经过卷积神经网络提取特征图；然后，RPN 在特征图上生成一系列的候选区域，并对这些候选区域进行初步的分类和位置回归；接着，根据 RPN 输出的候选区域，在特征图上提取对应的特征，并通过 ROI Pooling 层将这些特征映射到固定大小的特征向量；最后，将这些特征向量输入到全连接层进行最终的分类和位置回归，得到目标物体的类别和精确位置。</p><p>在实际应用中，目标检测面临着许多挑战。例如，目标物体的大小、形状、姿态变化多样，图像中的光照、遮挡、背景复杂等因素都会影响检测的准确性。为了解决这些问题，研究人员提出了许多改进方法。例如，使用多尺度训练和测试，以适应不同大小的目标物体；采用数据增强技术，如旋转、缩放、裁剪等，增加训练数据的多样性；引入注意力机制，让模型更加关注目标物体的关键区域。</p><h2 id="二、图像生成技术探秘" tabindex="-1">二、图像生成技术探秘 <a class="header-anchor" href="#二、图像生成技术探秘" aria-label="Permalink to &quot;二、图像生成技术探秘&quot;">​</a></h2><p>图像生成，是计算机视觉领域中另一个极具魅力的研究方向。它的目标是通过算法生成逼真的图像，这些图像可以是现实世界中存在的物体或场景，也可以是完全虚构的。图像生成技术的应用非常广泛，如艺术创作、游戏开发、虚拟现实、广告设计等。例如，艺术家可以利用图像生成技术创作出独特的艺术作品；游戏开发者可以使用它生成游戏中的场景和角色；在虚拟现实中，图像生成技术可以为用户提供更加逼真的虚拟环境。</p><p>图像生成技术主要包括基于生成对抗网络（GAN）和基于变分自编码器（VariationalAutoencoder，简称 VAE）的方法。GAN 由生成器和判别器组成，生成器负责生成图像，判别器则负责判断生成的图像是真实的还是伪造的。在训练过程中，生成器和判别器相互对抗，不断提高自己的能力，最终生成器能够生成逼真的图像。VAE 则是一种基于概率模型的图像生成方法，它通过对输入图像进行编码和解码，学习到图像的潜在表示，并利用这个潜在表示生成新的图像。</p><p>以 GAN 为例，它的工作原理可以简单理解为一个造假者和一个警察的博弈过程。生成器就像造假者，它试图生成逼真的图像来欺骗判别器；判别器则像警察，它要努力分辨出生成的图像是真实的还是伪造的。在训练过程中，生成器和判别器不断调整自己的参数，生成器生成的图像越来越逼真，判别器的分辨能力也越来越强。最终，当生成器生成的图像能够以假乱真，判别器无法分辨时，GAN 就达到了一个较好的训练效果。</p><p>GAN 有许多变体，如 DCGAN（Deep Convolutional Generative Adversarial Network）、WGAN（Wasserstein Generative Adversarial Network）、CycleGAN 等。DCGAN 通过使用卷积神经网络来构建生成器和判别器，使得生成的图像质量更高；WGAN 则通过改进损失函数，解决了传统 GAN 训练不稳定的问题；CycleGAN 可以实现图像风格的转换，例如将马的图像转换为斑马的图像。</p><p>图像生成技术在实际应用中也面临着一些挑战。例如，生成的图像可能存在细节模糊、不真实等问题；生成模型的训练需要大量的计算资源和时间；如何控制生成图像的内容和风格也是一个难题。为了解决这些问题，研究人员提出了许多改进方法。例如，使用多尺度训练和对抗训练，提高生成图像的质量；采用更高效的网络结构和训练算法，减少计算资源的消耗；引入条件生成技术，通过输入特定的条件来控制生成图像的内容和风格。</p><h2 id="三、强化学习在计算机视觉的应用案例" tabindex="-1">三、强化学习在计算机视觉的应用案例 <a class="header-anchor" href="#三、强化学习在计算机视觉的应用案例" aria-label="Permalink to &quot;三、强化学习在计算机视觉的应用案例&quot;">​</a></h2><p>深度强化学习在诸多决策领域已取得显著成果，尤其在游戏领域，多款游戏的 AI 水平已达到甚至超越人类。鉴于此，计算机视觉领域自然也会尝试运用这种颇具潜力的算法。不过，截至目前，我们尚未在该领域看到特别成功的案例。这或许是因为计算机视觉任务不像游戏那样，能直观地对应到一个明确的决策环境或可解释的动作步骤。尽管如此，在顶级学术会议中，我们依然能发现相关研究的身影，显示出其持续的探索价值。下面我们选择几个在计算机视觉中应用强化学习的代表性方法进行介绍。</p><p>早在 2014 年，Google DeepMind 团队就将深度强化学习应用到了注意力机制当中。这个绝妙的想法来自论文《Recurrent Models of Visual Attention》，Volodymyr Mnih 也是大名鼎鼎的DQN 的一作。如图 29-3 所示，相较于传统 CNN 用于手写体识别时，需在单张图像上对大量不同尺度扫描窗口做计算，能够在大幅减少此类计算量的同时，保持相当甚至更优性能。本质而言，该算法借助强化学习动态调节注意力位置，让位置调整朝着提升分类准确率的方向推进。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BC%BA%E5%8C%96%E5%AD%A6%E4%B9%A0%E5%BF%AB%E9%80%9F%E5%85%A5%E9%97%A8%E4%B8%8E%E5%AE%9E%E6%88%98/images/29/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BC%BA%E5%8C%96%E5%AD%A6%E4%B9%A0%E5%BF%AB%E9%80%9F%E5%85%A5%E9%97%A8%E4%B8%8E%E5%AE%9E%E6%88%98/images/29/3.png" alt=""></a></p><ul><li>图29-3 基于深度强化学习的注意力机制模型架构示意图</li></ul><p>具体来看，算法在 RNN 框架中引入强化学习机制。首先，依靠一个简单网络提取 Glimpse 特征：以特定中心为基准，进行多尺度采样，再对采样结果做特征提取，得到瞥见（glimpse）</p><h2 id="g" tabindex="-1">g <a class="header-anchor" href="#g" aria-label="Permalink to &quot;g&quot;">​</a></h2><p>表示</p><ul><li>。随后，利用该特征结合 RNN 中存储的历史状态信息，对另一个网络开展强化训练。​t</li></ul><h2 id="l" tabindex="-1">l <a class="header-anchor" href="#l" aria-label="Permalink to &quot;l&quot;">​</a></h2><h2 id="a" tabindex="-1">a <a class="header-anchor" href="#a" aria-label="Permalink to &quot;a&quot;">​</a></h2><p>经训练后，此网络一方面输出预测的下一注意力位置 ，另一方面输出当前位置的分类结果，分类的正确与否会对应产生当前时刻的收益反馈。</p><p>接下来我们再介绍一些经典的视觉任务当中使用强化学习的例子。</p><h2 id="_3-1-图像修复" tabindex="-1">3.1 图像修复 <a class="header-anchor" href="#_3-1-图像修复" aria-label="Permalink to &quot;3.1 图像修复&quot;">​</a></h2><p>使用 RL 做图像修复，来自 CVPR 2018 的论文《Crafting a Toolchain for Image Restorationby Deep Reinforcement Learning》。如图 29-4 所示，左图为被噪声干扰的图像，右图为去噪后的图像。我们能够想到的最直接的方式也就是采取滤波降噪等等。显然，我们也知道对于损害程度不同的地方，我们采取的滤波核和方式肯定不一样。那么，我们是否能够训练出一个网络，使得对于不同程度的情况采取不同的恢复方式呢？</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BC%BA%E5%8C%96%E5%AD%A6%E4%B9%A0%E5%BF%AB%E9%80%9F%E5%85%A5%E9%97%A8%E4%B8%8E%E5%AE%9E%E6%88%98/images/29/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BC%BA%E5%8C%96%E5%AD%A6%E4%B9%A0%E5%BF%AB%E9%80%9F%E5%85%A5%E9%97%A8%E4%B8%8E%E5%AE%9E%E6%88%98/images/29/4.png" alt=""></a></p><ul><li>图29-4 图像修复（左图：噪声图像；右图：去噪后图像）</li></ul><p>这个工作中，作者创建了一个工具箱，在这个工具箱当中，具备适合于不同情况的恢复工具，如不同核大小的高斯滤波器。进而，该工作设计了一个决策的网络，这个网络能够根据图片的状况选择最合适的工具来对图像进行修复。</p><p>图 29-5 展示了图像恢复算法的流程框架图，用于实现图像的迭代修复，核心是借强化学习让智能体选工具优化图像，以下结合流程和算法细节拆解。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BC%BA%E5%8C%96%E5%AD%A6%E4%B9%A0%E5%BF%AB%E9%80%9F%E5%85%A5%E9%97%A8%E4%B8%8E%E5%AE%9E%E6%88%98/images/29/5.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BC%BA%E5%8C%96%E5%AD%A6%E4%B9%A0%E5%BF%AB%E9%80%9F%E5%85%A5%E9%97%A8%E4%B8%8E%E5%AE%9E%E6%88%98/images/29/5.png" alt=""></a></p><ul><li>图29-5 图像修复强化学习框架示意图</li></ul><h3 id="_3-1-1-整体流程-多步迭代-以-step-1-到-step-t-为例" tabindex="-1">3.1.1 整体流程（多步迭代，以 Step 1 到 Step T 为例 ） <a class="header-anchor" href="#_3-1-1-整体流程-多步迭代-以-step-1-到-step-t-为例" aria-label="Permalink to &quot;3.1.1 整体流程（多步迭代，以 Step 1 到 Step T 为例 ）&quot;">​</a></h3><ol><li>输入与初始状态：</li></ol><h2 id="i" tabindex="-1">I <a class="header-anchor" href="#i" aria-label="Permalink to &quot;I&quot;">​</a></h2><h2 id="it" tabindex="-1">It <a class="header-anchor" href="#it" aria-label="Permalink to &quot;It&quot;">​</a></h2><h2 id="v1" tabindex="-1">v1 <a class="header-anchor" href="#v1" aria-label="Permalink to &quot;v1&quot;">​</a></h2><h2 id="s" tabindex="-1">S <a class="header-anchor" href="#s" aria-label="Permalink to &quot;S&quot;">​</a></h2><ul><li>初始输入为图像，搭配初始零向量，构成第一步状态；后续步骤里，（修复中​1​1​</li></ul><h2 id="vt" tabindex="-1">vt <a class="header-anchor" href="#vt" aria-label="Permalink to &quot;vt&quot;">​</a></h2><h2 id="s-1" tabindex="-1">S <a class="header-anchor" href="#s-1" aria-label="Permalink to &quot;S&quot;">​</a></h2><ul><li>图像）和（上一步的值向量）组成状态。​t​状态经 One - hot Encoder（独热编码）处理，把离散信息转化为可计算形式，再由Feature Extractor（特征提取器，用 3 层或 8 层 CNN 实现 ）提取图像特征，二者的输出一同输入 LSTM（长短期记忆网络，处理时序决策）。</li></ul><ol start="2"><li>智能体（Agent）决策与图像修复：</li></ol><h2 id="v" tabindex="-1">v <a class="header-anchor" href="#v" aria-label="Permalink to &quot;v&quot;">​</a></h2><h2 id="a-1" tabindex="-1">a <a class="header-anchor" href="#a-1" aria-label="Permalink to &quot;a&quot;">​</a></h2><ul><li>LSTM 输出值向量，智能体依据其最大值选动作，从 Toolbox（工具库）挑对应工具​t​t（含高斯滤波、JPEG 压缩等 12 种修复工具 + 1 个 stop 动作）。</li></ul><h2 id="i-1" tabindex="-1">I <a class="header-anchor" href="#i-1" aria-label="Permalink to &quot;I&quot;">​</a></h2><h2 id="i-2" tabindex="-1">I <a class="header-anchor" href="#i-2" aria-label="Permalink to &quot;I&quot;">​</a></h2><h2 id="f" tabindex="-1">f <a class="header-anchor" href="#f" aria-label="Permalink to &quot;f&quot;">​</a></h2><ul><li>选好工具后，经（恢复函数）对当前图像执行修复，得到，完成一步迭代；持t+1​r​t​</li></ul><h2 id="i-3" tabindex="-1">I <a class="header-anchor" href="#i-3" aria-label="Permalink to &quot;I&quot;">​</a></h2><ul><li>续此流程，直到选 “stop” 动作，输出最终图像。T+1​</li></ul><h3 id="_3-1-2-关键组件细节-关联算法内容" tabindex="-1">3.1.2 关键组件细节（关联算法内容） <a class="header-anchor" href="#_3-1-2-关键组件细节-关联算法内容" aria-label="Permalink to &quot;3.1.2 关键组件细节（关联算法内容）&quot;">​</a></h3><ul><li><p>Toolbox（工具库）：包含 12 种图像修复 / 处理工具（如高斯滤波去噪、JPEG 压缩模拟失真等 ）+ 1 个 “stop” 终止动作。工具基于 3 层或 8 层 CNN 实现，训练时会同步更新这些工具网络参数。</p></li><li><p>RL 网络（强化学习部分）： 用 DQN（深度 Q 网络），借 Bellman 不等式计算值函数“标签”，以“动作后图像信噪比（SNR）增量累计”作为奖励 Reward。对比“标签”和当前网络估</p></li><li><p>计值 V，更新网络，让智能体逐步学会选最优工具。</p></li></ul><h2 id="_3-2-目标跟踪" tabindex="-1">3.2 目标跟踪 <a class="header-anchor" href="#_3-2-目标跟踪" aria-label="Permalink to &quot;3.2 目标跟踪&quot;">​</a></h2><p>目标跟踪，亦称视频目标跟踪，指的是在视频序列中对首帧指定的目标进行持续标记（图 29-6）。相较于传统的目标识别任务，它面临着几大核心难点：训练样本匮乏、易出现误差累积，且对障碍物遮挡等场景的鲁棒性较差。</p><p>下面要介绍的这个案例是 CVPR 2017 的《Learning Policies for Adaptive Tracking with DeepFeature Cascades》，其研究重点聚焦于“基于检测的跟踪”算法。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BC%BA%E5%8C%96%E5%AD%A6%E4%B9%A0%E5%BF%AB%E9%80%9F%E5%85%A5%E9%97%A8%E4%B8%8E%E5%AE%9E%E6%88%98/images/29/6.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BC%BA%E5%8C%96%E5%AD%A6%E4%B9%A0%E5%BF%AB%E9%80%9F%E5%85%A5%E9%97%A8%E4%B8%8E%E5%AE%9E%E6%88%98/images/29/6.png" alt=""></a></p><ul><li>图29-6 目标检测</li></ul><p>在训练样本极度短缺的情况下，训练神经网络面临巨大挑战；若基于性能稳健的模型上进行微调，又会显著影响实时性。那么，在这一需要在准确度和计算性能进行动态权衡的问题中，强化学习是否可以发挥出独特优势呢？</p><p>基于强化学习的注意力机制，最直观的应用思路是借助该机制生成目标跟踪的候选区域。如图29-7 所示，常规目标跟踪任务会以上一次检测记录为基础，初始化多尺度、多位置的候选区域；引入强化学习后，网络能够给出明确的微调方向，进而提升检测效率。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BC%BA%E5%8C%96%E5%AD%A6%E4%B9%A0%E5%BF%AB%E9%80%9F%E5%85%A5%E9%97%A8%E4%B8%8E%E5%AE%9E%E6%88%98/images/29/7.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BC%BA%E5%8C%96%E5%AD%A6%E4%B9%A0%E5%BF%AB%E9%80%9F%E5%85%A5%E9%97%A8%E4%B8%8E%E5%AE%9E%E6%88%98/images/29/7.png" alt=""></a></p><ul><li>图29-7 基于强化学习的目标检测示意图</li></ul><p>不过，接下来要介绍的算法采用了不同思路。相较于将强化学习用于候选区域选择，该算法把强化学习应用于决策网络输出层数。简单来说，对于极易辨别的目标，或许无需经过网络完整计算获取最终特征，底层特征可能就具备良好的可辨别性；反之，面对遮挡、3D 旋转等复杂情形，可能要依靠更高层的语义信息才能完成区分。</p><p>图 29-8 下部展示了使用该网络处理两种不同的样本的区别。第一种背景简单，人物的面部为正面，是一个简单的识别场景，因此经过一层网络便可以进行分类了；相比之下，第二个样本是一个侧面面部，同时背景和前景的区分度不大，因此希望经过多层网络之后能够得到一个区分度比较大的高层特征。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BC%BA%E5%8C%96%E5%AD%A6%E4%B9%A0%E5%BF%AB%E9%80%9F%E5%85%A5%E9%97%A8%E4%B8%8E%E5%AE%9E%E6%88%98/images/29/8.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%BC%BA%E5%8C%96%E5%AD%A6%E4%B9%A0%E5%BF%AB%E9%80%9F%E5%85%A5%E9%97%A8%E4%B8%8E%E5%AE%9E%E6%88%98/images/29/8.png" alt=""></a></p><ul><li>图29-8 基于强化学习的检测框架在处理不同图像时的区别</li></ul><p>那这样做有什么好处呢？ 能够大幅度提高计算的效率，因为大量的样本，尤其是某个简单场景附近的场景，一般也是简单场景，也就是说场景几乎没有变化。因此，这种方式能够很好的提高计算的效率。</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>本讲围绕计算机视觉展开。我们先介绍了计算机视觉基础知识：旨在让计算机“理解”图像 / 视频，流程涵盖图像获取到目标识别，关键技术包括 CNN 等。进而详细介绍目标检测与图像生成技术，前者包含传统算法和基于深度学习的两类算法，面临多种挑战；后者以 GAN 和 VAE为核心，也需要解决诸多问题。</p><p>同时，还探讨了强化学习在计算机视觉领域的一些应用。虽成功案例有限，但在图像修复（通过智能体选工具迭代修复）和目标跟踪（决策网络输出层数提升效率）等方面，强化学习依旧展现出了潜力，为该领域发展提供了新方向和新思路。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><ol><li><p>请举例说明目标检测和图像生成技术在你生活中的应用场景，你认为这些应用还有哪些可以改进的地方？</p></li><li><p>在目标检测算法中，One-stage 算法和 Two-stage 算法各有什么优缺点？在实际应用中，如何选择合适的算法？</p></li></ol><p>希望你通过今天的学习，对强化学习有了清晰的认识。如果有任何疑问，欢迎在讨论区留言交流！</p>',97)])])}const c=a(n,[["render",r]]);export{A as __pageData,c as default};
